// ============================================================
// NODE NAME: Ask Selection      (Code · Run Once for All Items)
// Branch: Switch output "ask_selection"
// Parks a `selecting` row so the student's NEXT message ("2018") is understood
// as the year rather than falling through to the tutor.
// ============================================================

const r = $('Router').first().json;
const now = new Date().toISOString();
const prior = r.session || {};

// Numbered, and labelled by sitting — there are two papers for most years now, so a bare
// "• 2018" printed twice is both ambiguous and looks like a duplicate-row bug.
const exams = (r.available || []).filter(e => e && e.exam_id);
const list = exams.map((e, i) => `${i + 1}. ${e.label || e.year}`).join('\n');

// An empty list means the questions table came back without usable rows — say so
// instead of printing a heading with nothing under it, which reads like a bug.
let text;
if (!exams.length) {
  text = 'لا أجد امتحانات متاحة في الوقت الحالي. حاول مرّة أخرى بعد قليل، أو أخبر المسؤول عن التطبيق.';
} else if (Array.isArray(r.ambiguous) && r.ambiguous.length > 1) {
  const which = r.ambiguous
    .map(e => `${exams.findIndex(x => x.exam_id === e.exam_id) + 1}. ${e.label || e.year}`)
    .join('\n');
  text = `لهذه السنة دورتان. أيّهما تريد؟\n${which}\n\n_اكتب الرقم، أو «عادية» أو «استثنائية»._`;
} else if (r.unparsed) {
  text = `لم أتعرّف على اختيارك. اكتب رقم الامتحان من القائمة:\n${list}`;
} else {
  text = `أي امتحان تريد أن تتمرّن عليه؟ اكتب رقمه:\n${list}`;
}

// NocoDB updates a row by its own `Id`. Carry it forward when the row already
// exists, or a mistyped year creates a second `selecting` row instead of
// updating the first one.
const row = {
  session_id: r.session_id,
  exam_id: null,
  question_ids: JSON.stringify([]),
  current_index: 0,
  current_question_id: null,
  score_total: 0,
  points_total: 0,
  answers_log: JSON.stringify([]),
  status: 'selecting',
  started_at: prior.started_at || now,
  updated_at: now,
};
if (prior.Id != null) row.Id = prior.Id;

return [{ json: { action: 'ask_selection', session_row: row, reply_text: text } }];

// ============================================================
// NODE NAME: Grade          (Code · Run Once for All Items)
// Branch: Switch "grade"  ←  after 'Get Question' and 'Get Answer'
//
// This is the ONLY node in the workflow that reads the answers table, and it
// runs after the student has already submitted. Nothing upstream can leak the key.
// ============================================================

// ---- NocoDB row shape ----------------------------------------------------
// This NocoDB node wraps every row as { id, id_fields: { Id }, fields: {...} }.
// Flatten it so columns are readable directly, and lift the primary key to `Id`.
// Rows that are already flat pass through untouched, so this works either way.
function flat(j) {
  if (!j || typeof j !== 'object') return {};
  if (!j.fields || typeof j.fields !== 'object') return j;
  const out = Object.assign({}, j.fields);
  if (j.id_fields && j.id_fields.Id != null) out.Id = j.id_fields.Id;
  else if (j.Id != null) out.Id = j.Id;
  else if (j.id != null) out.Id = j.id;
  return out;
}
// --------------------------------------------------------------------------

const r = $('Router').first().json;
const question = flat($('Get Question').first().json);
const answerRow = flat($('Get Answer').first().json);
const studentRaw = String(r.student_answer || '').trim();

// The answer row MUST belong to the question being graded. If `Get Answer` has no
// Where clause (or a broken one) NocoDB happily returns row 1 of the table, and every
// question gets marked against someone else's key — silently, as a zero.
if (answerRow.question_id && question.question_id
    && String(answerRow.question_id) !== String(question.question_id)) {
  throw new Error(
    'Answer/question mismatch: Get Question returned "' + question.question_id +
    '" but Get Answer returned "' + answerRow.question_id +
    '". Check the Where clause on the Get Answer node.');
}
if (!answerRow.question_id) {
  throw new Error('Get Answer returned no row for "' + question.question_id +
    '". Check the Where clause on the Get Answer node.');
}

const type = question.type;
const pointsMax = Number(question.points_max ?? 0);
const parse = (v, f) => { if (v == null) return f; if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return f; } };
const correct = parse(answerRow.correct_answer, null);

function norm(t) {
  return String(t || '')
    .replace(/[\u064B-\u065F\u0670]/g, '')              // tashkeel
    .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')    // unify alef
    .replace(/\u0640/g, '')                            // tatweel: هـ is the letter ه
    .replace(/\u0649/g, '\u064A').replace(/\u0629/g, '\u0647')  // alef maqsura, ta marbuta
    .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))  // Arabic-Indic digits
    .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
}
function stem(w) {
  let x = w;
  if (x.length > 3) x = x.replace(/^[\u0648\u0641]/, '');
  if (x.length > 3) x = x.replace(/^[\u0628\u0643\u0644]/, '');
  if (x.length > 3) x = x.replace(/^\u0627\u0644/, '');
  return x;
}
const toks = t => norm(t).split(' ').filter(w => w.length > 1).map(stem);
function coverage(key, stu) {
  const kt = toks(key); if (!kt.length) return 0;
  const st = new Set(toks(stu)); let h = 0;
  for (const w of kt) if (st.has(w)) h++;
  return h / kt.length;
}

// ============================================================
// CHOICE PARSING — multi-answer aware, and works in both directions
// ------------------------------------------------------------
// Three real shapes across the papers, and the old parser handled only the first:
//
//   2018 odd_one_out   "1 - ج   2 - ب   3 - أ"          label = digit,  answer = ONE letter
//   2019_2 multi       "I- أ، ب  II- ب  III- ب، د"       label = roman,  answer = TWO letters
//   2019_2 matching    "أ- 3   ب- 1   ج- 2، 4"           label = LETTER, answer = digits
//
// It captured exactly one letter per label, so «أ، ب» silently became «أ» and a student who
// answered the question perfectly was marked half wrong. And it could not read the matching
// direction at all, because there the label is the Arabic letter and the answer is the number.
//
// Which side is which is not guessed — it is read off the KEY, which we already have.
// ------------------------------------------------------------
// After norm(), أ becomes ا (alef is unified) and ة becomes ه, so the option letters are
// ا ب ج د ه. Note what is NOT in that set: و. It is the conjunction in «أ و ب», and treating
// it as an option would turn every two-answer response into a three-answer one. No paper in
// this set labels an option past ه.
const OPTION_LETTERS = new Set(['\u0627', '\u0628', '\u062C', '\u062F', '\u0647']);

const isOptionLetter = w => w.length === 1 && OPTION_LETTERS.has(w);
const isDigitTok = w => /^\d{1,2}$/.test(w);
const isRomanTok = w => /^[ivx]{1,4}$/.test(w);

// Does this key answer with numbers (matching) or with letters (everything else)?
function keyValueKind(map) {
  for (const v of Object.values(map || {})) {
    for (const one of (Array.isArray(v) ? v : [v])) {
      if (/^\s*\d+\s*$/.test(String(one))) return 'digit';
    }
  }
  return 'letter';
}

// Returns { LABEL: [answers…] }, or { __single: [answers…] } when the student gave no labels
// at all — which is the normal way to answer a one-group question.
function parseChoices(text, valueKind) {
  const isValue = valueKind === 'digit' ? isDigitTok : isOptionLetter;
  const isLabel = valueKind === 'digit'
    ? isOptionLetter                                   // matching: أ- 3
    : (w => isRomanTok(w) || isDigitTok(w));           // everything else: I- أ  /  1 - ج
  // The two tests never overlap: when answers are digits the labels are letters, and vice
  // versa. That is what makes a single left-to-right scan unambiguous.

  const out = {};
  const loose = [];
  let cur = null;
  for (const w of norm(text).split(' ').filter(Boolean)) {
    if (isLabel(w)) { cur = w.toUpperCase(); if (!out[cur]) out[cur] = []; continue; }
    if (isValue(w)) { if (cur) out[cur].push(w); else loose.push(w); }
  }
  if (Object.keys(out).length) return out;
  return loose.length ? { __single: loose } : null;
}

const ROMAN = ['I','II','III','IV','V','VI','VII'];
function pick(given, label, i, labelCount) {
  if (!given) return [];
  // An unlabelled answer can only be meant for a question that has ONE item. Spreading it
  // across four groups would award the same letters to every group.
  if (given.__single) return labelCount === 1 ? given.__single : [];
  // norm(label) matters for the matching direction: the key labels its rows «أ» with the hamza,
  // while the student's parsed labels have been through norm(), where أ becomes ا. Comparing the
  // raw forms missed every hamza'd label and quietly dropped that pair's marks.
  for (const c of [String(label).toUpperCase(), norm(label).toUpperCase(),
                   String(i + 1), ROMAN[i]]) {
    if (c && Array.isArray(given[c])) return given[c];
  }
  return [];
}

// Score one item's answer SET against its key SET.
//
//   hits   — key answers the student gave
//   extras — answers the student gave that are not in the key
//
// credit = max(0, hits − extras) / |key|
//
// The subtraction is what stops «أ ب ج د» — listing everything — from scoring full marks on a
// two-answer item. One right and one wrong scores zero, which is the same standard the paper
// itself applies: the ministry's key gives 0.50 for the pair, not 0.25 per letter.
// A single-answer item is the same formula with |key| = 1, so nothing changes for those.
function scoreSet(keyVal, got) {
  const K = (Array.isArray(keyVal) ? keyVal : [keyVal])
    .map(x => norm(String(x))).filter(Boolean);
  const S = Array.from(new Set((got || []).map(x => norm(String(x))).filter(Boolean)));
  if (!K.length) return { frac: 0, hits: 0, extras: S.length, key: K, given: S };
  const ks = new Set(K);
  let hits = 0, extras = 0;
  for (const s of S) { if (ks.has(s)) hits++; else extras++; }
  return { frac: Math.max(0, hits - extras) / K.length, hits, extras, key: K, given: S };
}

const fmtSet = v => (Array.isArray(v) ? v : [v]).filter(x => x != null).join('، ');
const round2 = n => Math.round(n * 100) / 100;

const breakdown = [];
let score = null, needsLlm = false, llmPayload = null;

// A question whose key is a label→answer map: matching, odd_one_out, mcq_single, mcq_multi.
// Parse Canonical emits every label key the same way — { by_label, by_label_points } — so that
// per-item marks have somewhere to live. Rows extracted by the old LLM path store the bare map
// for odd_one_out/mcq instead, so fall back to it and keep those rows working.
const LABEL_TYPES = ['matching', 'odd_one_out', 'mcq_single', 'mcq_multi'];
const labelMap = (LABEL_TYPES.indexOf(type) === -1) ? null
  : (correct && correct.by_label)
    || (type !== 'matching' && correct && !correct.acceptable_elements
        && !correct.required_components && !('verdict' in correct) ? correct : null);

if (r.skipped || !studentRaw) {
  score = 0;
  breakdown.push({ item: null, note: 'skipped_or_empty', awarded: 0 });

} else if (labelMap && Object.keys(labelMap).length) {
  const labels = Object.keys(labelMap);
  // Per-item marks when the key states them — 2019_2's matching is 0.50 / 0.50 / 1.00, because
  // its third pair has two answers. Splitting pointsMax evenly would pay 0.67 for each and
  // quietly under-mark the one that is worth double. Falls back to an even split.
  const perMap = (correct && (correct.by_label_points || correct.points_by_label)) || null;
  const evenPer = pointsMax / labels.length;

  const given = parseChoices(studentRaw, keyValueKind(labelMap));
  let aw = 0;
  labels.forEach((L, i) => {
    const per = (perMap && perMap[L] != null) ? Number(perMap[L]) : evenPer;
    const got = pick(given, L, i, labels.length);
    const s = scoreSet(labelMap[L], got);
    const awarded = round2(per * s.frac);
    aw += awarded;
    breakdown.push({
      item: L,
      expected: fmtSet(labelMap[L]),
      got: s.given.length ? fmtSet(s.given) : null,
      hits: s.hits, extras: s.extras,
      awarded,
      points_max: round2(per),
    });
  });
  score = round2(aw);

} else if (type === 'correction' && correct) {
  // What actually has to be corrected is whatever appears in the model answer but NOT
  // in the question — here, العامة. Scoring against the whole corrected sentence instead
  // fails any student who answers concisely, which is most of them: "المصلحة العامة" is
  // a perfectly correct answer and used to score zero.
  const promptTokens = new Set(toks(question.prompt_text || ''));
  const es = Object.entries(correct), per = pointsMax / es.length;
  let aw = 0;
  es.forEach(([L, p]) => {
    const want = (p && p.correct) || '';
    const keyTokens = toks(want).filter(t => !promptTokens.has(t));

    let cov, basis;
    if (keyTokens.length) {
      const st = new Set(toks(studentRaw));
      cov = keyTokens.filter(t => st.has(t)).length / keyTokens.length;
      basis = 'key_terms';
    } else {
      // Model answer adds no new words (rare) — fall back to the whole sentence.
      cov = coverage(want, studentRaw);
      basis = 'full_sentence';
    }
    const ok = cov >= 0.6;
    if (ok) aw += per;
    breakdown.push({ item: L, expected: want, basis,
      key_terms: keyTokens, coverage: round2(cov), awarded: ok ? per : 0 });
  });
  score = round2(aw);

} else if (type === 'true_false' && correct && 'verdict' in correct) {
  // صح / خطأ, plus the correction when the verdict is خطأ. Both halves are required: a student
  // who says خطأ without saying what the right wording is has not finished the question.
  const saidTrue = /(?:^|\s)(\u0635\u062D|\u0635\u062D\u064A\u062D\u0647?)(?:\s|$)/.test(norm(studentRaw));
  const saidFalse = /(?:^|\s)(\u062E\u0637\u0627|\u063A\u0644\u0637)(?:\s|$)/.test(norm(studentRaw));
  const wantTrue = norm(correct.verdict).indexOf('\u0635\u062D') === 0;
  const verdictOk = wantTrue ? (saidTrue && !saidFalse) : (saidFalse && !saidTrue);

  if (!correct.correct) {
    score = verdictOk ? pointsMax : 0;
    breakdown.push({ item: 'verdict', expected: correct.verdict,
      got: saidTrue ? 'صح' : (saidFalse ? 'خطأ' : null), awarded: score });
  } else {
    const half = pointsMax / 2;
    const cov = coverage(correct.correct, studentRaw);
    const corrOk = cov >= 0.5;
    score = round2((verdictOk ? half : 0) + (corrOk ? half : 0));
    breakdown.push({ item: 'verdict', expected: correct.verdict,
      got: saidTrue ? 'صح' : (saidFalse ? 'خطأ' : null),
      awarded: verdictOk ? half : 0 });
    breakdown.push({ item: 'correction', expected: correct.correct,
      coverage: round2(cov), awarded: corrOk ? half : 0 });
  }

} else {
  needsLlm = true;
  let els = (correct && correct.acceptable_elements) || [];
  let req = (correct && correct.required_count) || null;

  // Some rubrics are shaped as required_components (e.g. "present each document:
  // type / source / main idea") rather than a flat list of acceptable elements.
  // Without this, the LLM is handed an EMPTY rubric and scores every such answer 0 —
  // which is what happened to the "قدم كلا من المستندين" question.
  if (!els.length && correct && Array.isArray(correct.required_components)) {
    const flatEls = [];
    correct.required_components.forEach(g => {
      (g.components || []).forEach(c => {
        const label = [g.group, c.label].filter(Boolean).join(' — ');
        flatEls.push(label ? label + ': ' + c.value : String(c.value));
      });
    });
    if (flatEls.length) {
      els = flatEls;
      req = flatEls.length;   // every component is required, not "any N of"
    }
  }
  const scored = els.map(e => ({ element: e, coverage: round2(coverage(e, studentRaw)) }))
    .sort((a, b) => b.coverage - a.coverage);
  const likely = scored.filter(s => s.coverage >= 0.5).map(s => s.element);
  llmPayload = {
    prompt_text: question.prompt_text,
    student_answer: studentRaw,
    points_max: pointsMax,
    required_count: req,
    acceptable_elements: els,
    required_components: (correct && correct.required_components) || null,
    likely_matches: likely,
  };
  breakdown.push(...scored.slice(0, 8));
  // provisional mark the LLM can override
  score = req ? round2(Math.min(likely.length, req) * (pointsMax / req)) : null;
}

// ---- a readable "the correct answer is…" line, shown whether they were right or wrong ----
let modelAnswer = '';
if (correct) {
  if (labelMap) {
    const arrow = (type === 'matching') ? ' ← ' : ': ';
    modelAnswer = Object.entries(labelMap)
      .map(([k, v]) => `${k}${arrow}${fmtSet(v)}`).join('  ·  ');
  } else if (type === 'correction') {
    modelAnswer = Object.values(correct)
      .map(p => `${p.wrong} ← ${p.correct}`).join('\n');
  } else if ('verdict' in correct) {
    modelAnswer = correct.correct
      ? `${correct.verdict}\n${correct.correct}` : String(correct.verdict);
  } else if (correct.acceptable_elements) {
    const need = correct.required_count;
    modelAnswer = (need ? `المطلوب ${need} من:\n` : '')
      + correct.acceptable_elements.map(e => `• ${e}`).join('\n');
  } else if (correct.required_components) {
    modelAnswer = correct.required_components.map(g =>
      `${g.group}:\n` + g.components.map(c => `• ${c.label}: ${c.value}`).join('\n')).join('\n\n');
  }
}

return [{
  json: {
    action: 'grade',
    model_answer: modelAnswer,
    question_id: question.question_id,
    type, points_max: pointsMax,
    score, needs_llm: needsLlm, llm_payload: llmPayload,
    breakdown, student_answer: studentRaw,
    skipped: Boolean(r.skipped),
    // flattened for the LLM node's prompt expressions
    q_prompt: question.prompt_text || '',
    q_elements: llmPayload ? (llmPayload.acceptable_elements || []).join(' | ') : '',
    q_required: llmPayload ? (llmPayload.required_count || '') : '',
  },
}];

// ============================================================
// NODE NAME: Router          (Code · Run Once for All Items)
// ------------------------------------------------------------
// Reads three upstream nodes by name. Those names must match EXACTLY:
//   'Chat Trigger'  · 'Get Session'  · 'List Exams'
// Outputs `action`, which the Switch routes on.
// Never touches the answers table.
// ============================================================

// ---- NocoDB row shape ----------------------------------------------------
// This NocoDB node wraps every row as { id, id_fields: { Id }, fields: {...} }.
// Flatten it so columns are readable directly, and lift the primary key to `Id`.
// Rows that are already flat pass through untouched, so this works either way.
function flat(j) {
  if (!j || typeof j !== 'object') return {};
  if (!j.fields || typeof j.fields !== 'object') return j;
  const out = Object.assign({}, j.fields);
  if (j.id_fields && j.id_fields.Id != null) out.Id = j.id_fields.Id;
  else if (j.Id != null) out.Id = j.Id;
  else if (j.id != null) out.Id = j.id;
  return out;
}
// --------------------------------------------------------------------------

const trigger = $('Chat Trigger').first().json;
const message = String(trigger.chatInput ?? trigger.message ?? trigger.text ?? '').trim();
const sessionId = String(trigger.sessionId ?? trigger.session_id ?? 'anon');

// Get Session is a "Get Many" with a where-clause, so it returns 0 or 1 rows.
let session = null;
try {
  const rows = $('Get Session').all().map(i => flat(i.json)).filter(r => r && r.session_id);
  session = rows[0] || null;
} catch (e) { session = null; }

// List Exams returns every question row's exam_id/year — collapse to distinct exams.
// Column names are read case-insensitively, and a missing `year` is recovered from
// the exam_id itself (civic_2018_1 → 2018) so one mistyped field option in the
// NocoDB node can't leave the student staring at an empty list.
function pick(row, name) {
  if (row[name] != null) return row[name];
  const want = name.toLowerCase();
  for (const k of Object.keys(row)) if (k.toLowerCase() === want) return row[k];
  return null;
}

let available = [];
try {
  const seen = new Set();
  $('List Exams').all().forEach(i => {
    const row = flat(i.json);
    const examId = pick(row, 'exam_id');
    if (!examId || seen.has(examId)) return;
    seen.add(examId);
    let yr = String(pick(row, 'year') ?? '').trim();
    if (!/^(19|20)\d{2}$/.test(yr)) {
      const m = String(examId).match(/(19|20)\d{2}/);
      yr = m ? m[0] : '';
    }
    // The suffix says which sitting it was: _1 عادية, _2 استثنائية. With seven papers across
    // four years the YEAR alone no longer identifies an exam, so carry the sitting too.
    const sess = String(examId).match(/_(\d+)$/);
    available.push({
      exam_id: examId,
      year: yr,
      session: sess ? Number(sess[1]) : null,
      label: yr + (sess && Number(sess[1]) === 2
        ? ' \u2014 \u0627\u0644\u062F\u0648\u0631\u0629 \u0627\u0644\u0627\u0633\u062A\u062B\u0646\u0627\u0626\u064A\u0629'
        : ' \u2014 \u0627\u0644\u062F\u0648\u0631\u0629 \u0627\u0644\u0639\u0627\u062F\u064A\u0629'),
    });
  });
} catch (e) { available = []; }
available.sort((a, b) => String(b.year).localeCompare(String(a.year))
  || (a.session || 0) - (b.session || 0));

// Fold every spelling variant a student might type down to one form. The patterns
// below are written in this normalised form — e.g. `اسئله`, not `أسئلة`.
const norm = s => String(s || '')
  .replace(/[\u064B-\u065F\u0670]/g, '')               // tashkeel
  .replace(/[\u0622\u0623\u0625\u0671]/g, '\u0627')     // آ أ إ ٱ → ا
  .replace(/\u0629/g, '\u0647')                         // ة → ه
  .replace(/\u0649/g, '\u064A')                         // ى → ي
  .replace(/\u0624/g, '\u0648')                         // ؤ → و
  .replace(/\u0626/g, '\u064A')                         // ئ → ي
  .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))  // ٠-٩ → 0-9
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const m = norm(message);
const WANTS_EXAM = /(امتحان|مسابقه|اسئله|سيله|تمرين|تدرب|تمرن|فحص|exam|quiz|test|practice)/.test(m);
const WANTS_STOP = /(انهاء|انهي|توقف|وقف|كفي|خلص|بطل|stop|end|quit|exit)/.test(m);
const WANTS_SKIP = /(تخطي|تخط|تجاوز|مرق|skip)/.test(m);
// An explicit escape hatch so a student can ask for help mid-exam without it
// being marked as their answer.
const WANTS_HELP = /^(سوال|اسال|اساله|ساعدني|وضحلي|help|ask)\s*[:：]/.test(m);
// "yes, next question" — only consulted while waiting for the student to continue.
// Two tiers, because some yes-words are also ordinary words.
//  STRONG — unambiguous; may be followed by more text ("نعم كمل من فضلك").
//  BARE   — only counts as yes when it IS the whole message; "اي" opens "اي شي تاني",
//           "تمام" opens "تمام بس ما فهمت", and neither of those means "next question".
// \b is useless here: it only knows [A-Za-z0-9_] and never matches after an Arabic letter.
const STRONG = '(ايوه|ايه|اكيد|التالي|نعم|كملي|كمل|تابع|okay|yes|yep|next)';
const BARE = '(اي|اجل|طبعا|تمام|ماشي|هيا|يلا|ok|go|y)';
const SAYS_YES = new RegExp('^' + STRONG + '(?![\\u0621-\\u064A\\w])').test(m)
  || new RegExp('^' + BARE + '$').test(m)
  || /(نعم|كمل|تابع|السوال التالي|next question)/.test(m);

function parseSelection(text) {
  const t = norm(text);
  const y = t.match(/\b(19|20)\d{2}\b/);
  // A bare small number is the student picking a line off the numbered list. Only counts when
  // it is the WHOLE message, so "2018" is never mistaken for item 2018 and a year inside a
  // sentence is never mistaken for an index.
  const idx = /^\s*([1-9]\d?)\s*$/.exec(t);
  // "عادية" / "استثنائية", or the shapes 2018-1 / 2018/2 that people type naturally.
  let sitting = null;
  // Written in the NORMALISED form, as the comment on norm() insists: ئ becomes ي and ى becomes
  // ي, so «استثنائية» arrives here as «استثناييه». Spelling these the natural way silently
  // matched nothing.
  if (/(عاديه|الاولي|اولي|first)/.test(t)) sitting = 1;
  if (/(استثنايي|الثانيه|ثانيه|second)/.test(t)) sitting = 2;
  const dashed = t.match(/\b(?:19|20)\d{2}\s*[-\/]\s*([12])\b/);
  if (dashed) sitting = Number(dashed[1]);
  return {
    year: y ? y[0] : null,
    subject: /(تربيه|وطنيه|مدنيه|civic)/.test(t) ? 'civic' : null,
    index: (idx && !y) ? Number(idx[1]) : null,
    sitting,
  };
}

function out(action, extra) {
  return [{
    json: Object.assign({
      action,
      session_id: sessionId,
      message,
      // The AI Agent's "take from previous node automatically" looks for `chatInput`.
      // It used to sit right after the Chat Trigger and get it for free; behind the
      // Router it sees this item instead, so pass the student's words through.
      chatInput: message,
      available,
    }, extra || {}),
  }];
}

// 1 — an active exam claims the turn
if (session && session.status === 'active') {
  if (WANTS_STOP) return out('finish', { session });
  if (WANTS_HELP) return out('passthrough', { session });
  if (WANTS_SKIP) {
    return out('grade', { session, student_answer: '', skipped: true,
      current_question_id: session.current_question_id });
  }
  return out('grade', { session, student_answer: message,
    current_question_id: session.current_question_id });
}

// 2 — graded, waiting for "yes, next question"
if (session && session.status === 'awaiting_next') {
  if (WANTS_STOP) return out('finish', { session });
  if (SAYS_YES) return out('serve_next', { session });
  // Anything else is a follow-up about the answer they just saw — let the tutor take it.
  // The session stays in awaiting_next, so "نعم" still works on the turn after.
  return out('passthrough', { session });
}

// 3 — waiting for the student to name subject + year
if (session && session.status === 'selecting') {
  if (WANTS_STOP) return out('finish', { session });
  const { year, subject, index, sitting } = parseSelection(message);

  // Picking a line off the numbered list.
  if (index && index <= available.length) {
    const e = available[index - 1];
    return out('start', { session, exam_id: e.exam_id, year: e.year });
  }
  // Nothing recognisable in the message — re-ask. Without this guard the find()
  // below matches on all-null criteria and silently starts whichever exam is first.
  if (!year && !subject) return out('ask_selection', { session, unparsed: true });

  const matches = available.filter(e =>
    (!year || String(e.year) === year)
    && (!subject || String(e.exam_id).startsWith(subject))
    && (!sitting || e.session === sitting));
  if (!matches.length) return out('ask_selection', { session, unparsed: true });
  // A year with two sittings is not a choice — ask which, rather than silently taking the first.
  if (matches.length > 1) return out('ask_selection', { session, ambiguous: matches });
  return out('start', { session, exam_id: matches[0].exam_id, year: matches[0].year });
}

// 4 — no exam in progress
if (WANTS_EXAM) {
  const { year, subject, sitting } = parseSelection(message);
  const matches = available.filter(e =>
    year && String(e.year) === year
    && (!subject || String(e.exam_id).startsWith(subject))
    && (!sitting || e.session === sitting));
  if (matches.length === 1) return out('start', { exam_id: matches[0].exam_id, year: matches[0].year });
  if (matches.length > 1) return out('ask_selection', { ambiguous: matches });
  return out('ask_selection', {});
}

return out('passthrough', { session });

// ============================================================
// NODE NAME: Finalize        (Code · Run Once for All Items)
// Branch: Switch "grade"  ←  after 'Grade' (and after 'Feedback LLM' when it ran)
// Records the mark, advances the index, and picks the next question.
// ============================================================

const r = $('Router').first().json;
const g = $('Grade').first().json;
const prior = r.session || {};
const now = new Date().toISOString();

const parse = (v, f) => { if (v == null) return f; if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return f; } };

// If the LLM branch ran, take its mark; otherwise the code's mark stands.
// Pull the last well-formed JSON object out of a model reply. A greedy
// /\{[\s\S]*\}/ fails the moment the model wraps its answer in <think> tags or
// prose containing braces — qwen3 does both — so scan brace-balanced candidates
// from the end and take the first one that actually parses.
function extractJson(text) {
  const clean = String(text)
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```(?:json)?/gi, '');
  const starts = [];
  for (let i = 0; i < clean.length; i++) if (clean[i] === '{') starts.push(i);
  for (let s = starts.length - 1; s >= 0; s--) {
    let depth = 0, inStr = false, esc = false;
    for (let i = starts[s]; i < clean.length; i++) {
      const c = clean[i];
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') {
        depth--;
        if (depth === 0) {
          try { return JSON.parse(clean.slice(starts[s], i + 1)); } catch (e) { }
          break;
        }
      }
    }
  }
  return null;
}

// Rescue readable Arabic feedback from a reply that wasn't valid JSON.
function salvage(text) {
  const stripped = String(text).replace(/<think>[\s\S]*?<\/think>/gi, '');
  const kept = stripped.split('\n').filter(line => {
    const t = line.trim();
    if (!t) return false;
    // Drop lines that are mostly Latin script — that's the model thinking, not feedback.
    const ar = (t.match(/[\u0600-\u06FF]/g) || []).length;
    const la = (t.match(/[A-Za-z]/g) || []).length;
    if (la >= ar) return false;
    // Drop bare headings the model likes to insert.
    if (/^(التحليل|النتيجة|الشرح|الاجابة|الإجابة|التقييم)\s*:?\s*$/.test(t)) return false;
    return true;
  });
  let out = kept.join(' ').replace(/\s+/g, ' ').trim();
  if (!out) return null;
  const sentences = out.match(/[^.!\u061F]+[.!\u061F]?/g) || [out];
  out = sentences.slice(0, 3).join(' ').trim();
  if (out.length > 400) out = out.slice(0, 400).replace(/\s\S*$/, '') + '\u2026';
  return out || null;
}

let awarded = Number(g.score ?? 0);
let feedback = null;
if (g.needs_llm) {
  try {
    const raw = $('Feedback LLM').first().json;
    const txt = raw.text ?? raw.output ?? raw.response ?? '';
    const j = extractJson(txt);
    if (j) {
      if (typeof j.score === 'number' && isFinite(j.score)) {
        awarded = Math.max(0, Math.min(g.points_max, j.score));
      }
      feedback = j.feedback || null;
    } else {
      // No parseable JSON. Do NOT print the raw reply — qwen3 reasons out loud, often in
      // English, and a student should never see the model's scratchpad. Salvage only the
      // Arabic prose, drop section labels, and cap it at a few sentences.
      feedback = salvage(txt);
    }
  } catch (e) { /* LLM branch didn't run — keep the code's provisional mark */ }
}
awarded = Math.round(awarded * 100) / 100;

const ids = parse(prior.question_ids, []);
const log = parse(prior.answers_log, []);
log.push({
  question_id: g.question_id,
  student_answer: g.student_answer,
  score: awarded,
  points_max: g.points_max,
  skipped: Boolean(g.skipped),
});

const nextIndex = Number(prior.current_index || 0) + 1;
const nextId = ids[nextIndex] || null;
const scoreTotal = Math.round((Number(prior.score_total || 0) + awarded) * 100) / 100;

const row = {
  session_id: r.session_id,
  exam_id: prior.exam_id || null,
  question_ids: JSON.stringify(ids),
  current_index: nextIndex,
  current_question_id: nextId,
  score_total: scoreTotal,
  points_total: Number(prior.points_total || 0),
  answers_log: JSON.stringify(log),
  // 'awaiting_next' = graded, waiting for the student to say yes before the next question
  status: nextId ? 'awaiting_next' : 'finished',
  started_at: prior.started_at || now,
  updated_at: now,
};
if (prior.Id != null) row.Id = prior.Id;   // NocoDB updates by Id, not by session_id

return [{
  json: {
    action: 'grade',
    session_row: row,
    result: {
      awarded,
      points_max: g.points_max,
      type: g.type,
      breakdown: g.breakdown || [],
      model_answer: g.model_answer || '',
      feedback,
      skipped: Boolean(g.skipped),
    },
    next_question_id: nextId,
    finished: !nextId,
    summary: { answered: log.length, of: ids.length, score: scoreTotal, out_of: Number(prior.points_total || 0) },
  },
}];

