parameters.jsCode:
// ============================================================
// NODE NAME: Compose Reply     (Code · Run Once for All Items)
// LAST node on every exam branch — whatever it outputs is what the student sees.
// All branches converge here, so it works out which one ran.
// ============================================================

// ---- NocoDB row shape ----------------------------------------------------
// This NocoDB node wraps every row as { id, id_fields: { Id }, fields: {...} }.
// Flatten it so columns are readable directly, and lift the primary key to `Id`.
// Rows that are already flat pass through untouched, so this works either way.
function flat(j) {
  if (!j || typeof j !== 'object') return {};
  if (!j.fields || typeof j.fields !== 'object') return j;
  const out = Object.assign({}, j.fields);
  if (j.id_fields && j.id_fields.Id != null) out.Id = j.id_fields.Id;
  else if (j.Id != null) out.Id = j.Id;
  else if (j.id != null) out.Id = j.id;
  return out;
}
// --------------------------------------------------------------------------

function from(name) { try { return $(name).first().json; } catch (e) { return null; } }

const ask = from('Ask Selection');
const start = from('Start Session');
const fin = from('Finalize');
const nxt = from('Serve Next');
const rawNext = from('Get Next Question');
const nextQ = rawNext ? flat(rawNext) : null;

const LETTERS = ['أ', 'ب', 'ج', 'د', 'ه', 'و'];
const parse = (v, f) => { if (v == null) return f; if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return f; } };

// An answer-format example sized to THIS question. A fixed "1-د، 2-أ، 3-ه، 4-ج"
// shows four pairs and a letter ه on a question that only has two of each.
function hint(n) {
  const out = [];
  for (let i = 0; i < n; i++) out.push(`${i + 1}-${LETTERS[i % LETTERS.length]}`);
  return out.join('\u060C ');
}

// Groups are labelled I, II, III — not 1, 2, 3. Showing "1-أ" against a question that displays
// "I—" makes the student guess at the format, and on a MULTI-answer question a one-letter
// example quietly costs them half the marks on every group that wants two.
function groupHint(groups, multi) {
  const parts = groups.map((g, i) => {
    const label = g.group_label || String(i + 1);
    return multi && i === 0 ? `${label}-\u0623\u060C\u0628` : `${label}-${LETTERS[i % LETTERS.length]}`;
  });
  return parts.join('\u060C ');
}

// ---- render one question the way a student should see it ----
function renderQuestion(q, n, of) {
  // Get Next Question has Always Output Data on, so an exhausted exam yields an
  // empty item rather than nothing — treat that as no question.
  if (!q || !q.question_id) return '';
  const lines = [];
  lines.push(`**السؤال ${n} من ${of}** · ${q.points_max} علامة`);
  if (q.context_text) lines.push(`\n> ${String(q.context_text).replace(/\n/g, '\n> ')}`);
  lines.push(`\n${q.prompt_text}`);

  const payload = parse(q.payload, null);
  if (payload && payload.groups) {
    payload.groups.forEach(g => {
      lines.push(`\n**${g.group_label}—** ${g.group_title}:`);
      lines.push(g.options.map((o, i) => `${LETTERS[i]}. ${o}`).join('  ·  '));
    });
    const multi = q.type === 'mcq_multi';
    lines.push('\n_' + (multi ? '\u0644\u0643\u0644 \u0645\u062C\u0645\u0648\u0639\u0629 \u062D\u0631\u0641 \u0648\u0627\u062D\u062F \u0623\u0648 \u0623\u0643\u062B\u0631. ' : '')
      + '\u0627\u0643\u062A\u0628 \u0625\u062C\u0627\u0628\u062A\u0643 \u0647\u0643\u0630\u0627: ' + groupHint(payload.groups, multi) + '_');
  } else if (payload && payload.matching_left) {
    lines.push('');
    payload.matching_left.forEach((l, i) => lines.push(`${i + 1}. ${l}`));
    lines.push('');
    payload.matching_right.forEach((rr, i) => lines.push(`${LETTERS[i]}. ${rr}`));
    lines.push(`\n_اكتب إجابتك هكذا: ${hint(payload.matching_left.length)}_`);

  // No payload to show, but these two types still need the student to know the shape.
  } else if (q.type === 'true_false') {
    lines.push('\n_\u0627\u0643\u062A\u0628 \u00AB\u0635\u062D\u00BB \u0623\u0648 \u00AB\u062E\u0637\u0623\u00BB\u060C '
      + '\u0648\u0625\u0630\u0627 \u0643\u0627\u0646\u062A \u062E\u0637\u0623 \u0641\u0627\u0643\u062A\u0628 \u0627\u0644\u062A\u0635\u062D\u064A\u062D._');
  } else if (q.type === 'correction') {
    lines.push('\n_\u0627\u0643\u062A\u0628 \u0627\u0644\u0643\u0644\u0645\u0629 \u0623\u0648 \u0627\u0644\u0639\u0628\u0627\u0631\u0629 \u0627\u0644\u0635\u062D\u064A\u062D\u0629 \u0628\u062F\u0644 \u0627\u0644\u062E\u0627\u0637\u0626\u0629._');
  }
  return lines.join('\n');
}

let text = '';

// ---- branch: ask_selection ----
if (ask && ask.action === 'ask_selection') {
  text = ask.reply_text;

// ---- branch: start ----
} else if (start && start.action === 'start') {
  if (start.finished) {
    text = 'لا توجد أسئلة جاهزة لهذا الامتحان بعد.';
  } else {
    const ids = parse(start.session_row.question_ids, []);
    text = `${start.intro}\n\n---\n\n${renderQuestion(start.next_question, 1, ids.length)}`;
  }

// ---- branch: grade — feedback + the correct answer, then ask before moving on ----
} else if (fin && fin.action === 'grade') {
  const res = fin.result, s = fin.summary;
  const pct = res.points_max ? res.awarded / res.points_max : 0;
  const mark = pct >= 0.999 ? '✅' : (pct > 0 ? '🟡' : '❌');
  const parts = [];

  parts.push(res.skipped
    ? `تخطّيت هذا السؤال. (0 من ${res.points_max})`
    : `${mark} **${res.awarded} من ${res.points_max}**`);

  if (res.feedback) parts.push(res.feedback);

  // Always show the model answer — right or wrong, this is the point of practising.
  if (res.model_answer) parts.push(`**الإجابة النموذجية:**\n${res.model_answer}`);

  parts.push(`_المجموع: ${s.score} من ${s.out_of} — أجبت ${s.answered} من ${s.of}_`);

  if (fin.finished) {
    const p = s.out_of ? Math.round(s.score / s.out_of * 100) : 0;
    parts.push(`---\n\n**انتهى الامتحان.** نتيجتك ${s.score} من ${s.out_of} (${p}%).`);
  } else {
    parts.push(`---\n\nهل تريد الانتقال إلى السؤال التالي؟ اكتب **نعم** للمتابعة، أو اسألني عن هذه الإجابة إذا لم تتضح لك.`);
  }
  text = parts.join('\n\n');

// ---- branch: serve_next — the student said yes ----
} else if (nxt && nxt.action === 'serve_next') {
  const row = nxt.session_row;
  const ids = parse(row.question_ids, []);
  text = renderQuestion(nextQ, Number(row.current_index) + 1, ids.length);
  // Shouldn't happen — serve_next only fires while a next question exists — but an
  // empty chat bubble is the worst possible failure, so never return one.
  if (!text) text = 'لم أعثر على السؤال التالي. اكتب **امتحان** للبدء من جديد.';

// ---- branch: finish — the student stopped early ----
} else if (nxt && nxt.action === 'finish') {
  const s2 = nxt.summary || { score: 0, out_of: 0, answered: 0, of: 0 };
  const p = s2.out_of ? Math.round(s2.score / s2.out_of * 100) : 0;
  text = `**أنهيت الامتحان مبكرًا.**\n\nأجبت عن ${s2.answered} من أصل ${s2.of} أسئلة.`
    + `\nنتيجتك ${s2.score} من ${s2.out_of} (${p}%).`
    + `\n\nاكتب **امتحان** متى شئت للبدء من جديد.`;

} else {
  text = 'حدث خطأ غير متوقع. اكتب "امتحان" للبدء من جديد.';
}

if (!text || !String(text).trim()) {
  text = 'حدث خطأ غير متوقع. اكتب "امتحان" للبدء من جديد.';
}

return [{ json: { output: text, text } }];

// ============================================================
// NODE NAME: Serve Next        (Code · Run Once for All Items)
// Branches: Switch outputs "serve_next" AND "finish" — both wire into this node.
//   serve_next → the student said yes. Flip the session back to active;
//                current_question_id already points at the right question,
//                Finalize advanced it at grading time.
//   finish     → the student typed توقف. Close the session out at its current score.
// ============================================================

const r = $('Router').first().json;
const prior = r.session || {};
const finishing = r.action === 'finish';

const parse = (v, f) => { if (v == null) return f; if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return f; } };
const ids = parse(prior.question_ids, []);
const log = parse(prior.answers_log, []);

// Rebuild the row field by field rather than spreading `prior` — the raw NocoDB
// row also carries read-only system columns (CreatedAt, UpdatedAt) that the
// write would choke on.
const row = {
  session_id: prior.session_id,
  exam_id: prior.exam_id || null,
  question_ids: prior.question_ids,
  current_index: Number(prior.current_index || 0),
  current_question_id: prior.current_question_id,
  score_total: Number(prior.score_total || 0),
  points_total: Number(prior.points_total || 0),
  answers_log: prior.answers_log,
  status: finishing ? 'finished' : 'active',
  started_at: prior.started_at,
  updated_at: new Date().toISOString(),
};
if (prior.Id != null) row.Id = prior.Id;

return [{
  json: {
    action: finishing ? 'finish' : 'serve_next',
    session_row: row,
    summary: {
      answered: log.length,
      of: ids.length,
      score: Number(prior.score_total || 0),
      out_of: Number(prior.points_total || 0),
    },
  },
}];

// ============================================================
// NODE NAME: Start Session      (Code · Run Once for All Items)
// Branch: Switch "start"  ←  after 'Get Questions'
// Builds the ordered question list and the first question's text.
// ============================================================

// ---- NocoDB row shape ----------------------------------------------------
// This NocoDB node wraps every row as { id, id_fields: { Id }, fields: {...} }.
// Flatten it so columns are readable directly, and lift the primary key to `Id`.
// Rows that are already flat pass through untouched, so this works either way.
function flat(j) {
  if (!j || typeof j !== 'object') return {};
  if (!j.fields || typeof j.fields !== 'object') return j;
  const out = Object.assign({}, j.fields);
  if (j.id_fields && j.id_fields.Id != null) out.Id = j.id_fields.Id;
  else if (j.Id != null) out.Id = j.Id;
  else if (j.id != null) out.Id = j.id;
  return out;
}
// --------------------------------------------------------------------------

const r = $('Router').first().json;
const now = new Date().toISOString();
const prior = r.session || {};   // the 'selecting' row, when the student got here via a question

const rows = $('Get Questions').all().map(i => flat(i.json));

// needs_review rows never reach a student — their answer key is known to be wrong.
const isClean = v => v === false || v === 'false' || v === 0 || v === '0' || v == null;
const ordered = rows
  .filter(q => q.question_id && isClean(q.needs_review))
  .sort((a, b) => (Number(a.domain) - Number(b.domain))
    || String(a.question_id).localeCompare(String(b.question_id)));

const ids = ordered.map(q => q.question_id);
const pointsTotal = Math.round(ordered.reduce((s, q) => s + Number(q.points_max || 0), 0) * 100) / 100;
const first = ordered[0] || null;

// Arabic counts don't take a bare numeral the way English does.
function qCount(n) {
  if (n === 0) return '\u0644\u0627 \u0623\u0633\u0626\u0644\u0629';                 // لا أسئلة
  if (n === 1) return '\u0633\u0624\u0627\u0644 \u0648\u0627\u062d\u062f';        // سؤال واحد
  if (n === 2) return '\u0633\u0624\u0627\u0644\u0627\u0646';                      // سؤالان
  if (n >= 3 && n <= 10) return `${n} \u0623\u0633\u0626\u0644\u0629`;              // N أسئلة
  return `${n} \u0633\u0624\u0627\u0644\u064b\u0627`;                              // N سؤالًا
}

// Reuse the `selecting` row rather than leaving it orphaned beside a new one.
const row = {
  session_id: r.session_id,
  exam_id: r.exam_id,
  question_ids: JSON.stringify(ids),
  current_index: 0,
  current_question_id: ids[0] || null,
  score_total: 0,
  points_total: pointsTotal,
  answers_log: JSON.stringify([]),
  status: ids.length ? 'active' : 'finished',
  started_at: prior.started_at || now,
  updated_at: now,
};
if (prior.Id != null) row.Id = prior.Id;

return [{
  json: {
    action: 'start',
    session_row: row,
    intro: ids.length === 0
      ? `لا توجد أسئلة جاهزة لامتحان ${r.year} حاليًا.`
      : `سنبدأ امتحان ${r.year}. ${qCount(ids.length)}، المجموع ${pointsTotal} علامة.`
        + (rows.length > ids.length
          ? ` (استُبعد ${qCount(rows.length - ids.length)} بحاجة إلى مراجعة.)` : ''),
    next_question: first,
    finished: ids.length === 0,
  },
}];

// ============================================================
// NODE NAME: Parse Canonical      (Code · Run Once for All Items)
// Position: straight after the Google Drive download node.
// Replaces: LlamaParse + Pre-extraction + Qwen HTTP + Post-extraction.
// Feeds: the same Switch on `recordType` → questions / answers / materials.
//
// Reads a canonical exam markdown (see canonical_format_SPEC.md) and emits the rows
// directly. There is no model in this path, so there is nothing to hallucinate, nothing
// to re-run differently tomorrow, and nothing to repair downstream.
//
// DESIGN RULE: a file that breaks the spec THROWS. It does not emit a half-row with a
// flag on it. A flag means "a human should look at this exam"; a spec violation means
// "the markdown is wrong, go fix the markdown". Conflating the two is how 2018 shipped
// fourteen questions with four silently broken answers.
// ============================================================

// ---------- 0. Get the text out of the Drive node ----------
// The Drive node hands the file over as BINARY, not text, and how that binary reaches a Code
// node depends on the instance: with binary data mode "memory" the base64 sits on
// item.binary.<key>.data, but with mode "filesystem" — and on some task-runner setups — only
// metadata comes through (fileName, mimeType, fileSize, id) and there is no base64 at all.
//
// So this does not guess. It tries each source in turn, checks that what it got actually looks
// like a canonical file, and if not it reports exactly what it saw. A wrong guess here used to
// surface much later as "the file has no **exam_id:** line", which points at the markdown when
// the markdown is fine.
function looksCanonical(t) {
  return typeof t === 'string' && t.indexOf('**exam_id:**') !== -1;
}

function readSource() {
  const item = $input.first();
  const j = item.json || {};
  const bin = item.binary || {};
  const tried = [];

  // 1. Already text on the item (an Extract From File node upstream, or a manual paste).
  for (const field of ['text', 'data', 'content', 'markdown']) {
    const v = j[field];
    if (typeof v === 'string' && v.length > 40) {
      if (looksCanonical(v)) return v;
      tried.push('json.' + field + ' (' + v.length + ' chars, no **exam_id:**)');
    }
  }

  // 2. Binary, base64-decoded. Try every binary property, not just the first.
  for (const key of Object.keys(bin)) {
    const b = bin[key] || {};
    if (typeof b.data === 'string' && b.data.length) {
      let decoded = '';
      try { decoded = Buffer.from(b.data, 'base64').toString('utf8'); } catch (e) { decoded = ''; }
      if (looksCanonical(decoded)) return decoded;
      // A few characters where a whole file should be is a REFERENCE, not content.
      tried.push('binary.' + key + (b.data.length < 200
        ? ' holds only ' + b.data.length + ' characters — that is a reference, not the file.'
        : ' decoded to ' + decoded.length + ' characters but has no **exam_id:** line: '
          + JSON.stringify(decoded.slice(0, 120))));
    } else if (b.id) {
      tried.push('binary.' + key + ' carries an id and no base64.');
    } else {
      tried.push('binary.' + key + ' has neither data nor id: ' + JSON.stringify(Object.keys(b)));
    }
  }

  const binaryUnavailable = Object.keys(bin).some(k => {
    const b = bin[k] || {};
    return b.id || (typeof b.data === 'string' && b.data.length < 200);
  });

  throw new Error('Parse Canonical: could not read the canonical markdown off the input item.\n'
    + 'json keys: ' + JSON.stringify(Object.keys(j)) + '\n'
    + 'binary keys: ' + JSON.stringify(Object.keys(bin)) + '\n'
    + (tried.length ? 'tried:\n  - ' + tried.join('\n  - ')
                    : 'nothing on the item looked like text or binary at all.')
    + (binaryUnavailable
      ? '\n\nThe binary is present but its CONTENT is not. n8n does not hand binary payloads to '
        + 'Code nodes when they run in a task runner, and the filesystem binary mode has the same '
        + 'effect. Fix: add an "Extract From File" node between the Drive node and this one — '
        + 'operation "Extract From Text File", destination output field "data" — and this node '
        + 'will read the text off json.data.'
      : ''));
}

const SRC = readSource().replace(/\r\n/g, '\n');

// ---------- 1. Small helpers ----------
const MARK_RE = /\((\d+\.\d{1,2})\)/;                     // (2.00) — the ONLY mark notation
const AR_LETTER = '[\\u0621-\\u064A]';

function trim(s) { return String(s == null ? '' : s).trim(); }
function num(s) { return Math.round(parseFloat(s) * 100) / 100; }
function fail(msg) { throw new Error('Parse Canonical: ' + msg); }

// A "> …" line is a note for whoever maintains the file — never content. It has to be
// recognised on the RAW line: clean() strips the marker, so filtering after cleaning lets the
// note through. The first one in the file landed inside a key block and threw.
function isNote(raw) { return /^\s*>/.test(String(raw)); }

// Strip the bold markers that only exist for human readers, and collapse a markdown link to its
// visible text. Editors auto-linkify a bare URL on the way into Drive — 2018's document source
// went in as "www.lebarmy.gov.lb" and came back as "[www.lebarmy.gov.lb](https://www.lebarmy.gov.lb)",
// which is what the student would then have been shown, and what the source key would have been
// graded against.
function clean(line) {
  return trim(String(line)
    .replace(/\*\*/g, '')
    .replace(/\[([^\]]+)\]\((?:[^)]*)\)/g, '$1'));
}

// ---------- 2. File header ----------
function headerField(name) {
  const m = SRC.match(new RegExp('\\*\\*' + name + ':\\*\\*\\s*([^\\n]+)'));
  return m ? trim(m[1]) : null;
}
const examId = headerField('exam_id');
if (!examId) {
  fail('the file has no exam_id header line. First 200 characters of what was read:\n'
    + JSON.stringify(SRC.slice(0, 200)));
}
const year = headerField('\\u0627\\u0644\\u0633\\u0646\\u0629');          // السنة
const fileTotalRaw = headerField('\\u0627\\u0644\\u0645\\u062C\\u0645\\u0648\\u0639'); // المجموع
const fileTotal = fileTotalRaw && MARK_RE.test(fileTotalRaw)
  ? num(fileTotalRaw.match(MARK_RE)[1]) : null;

// ---------- 3. Split into domains ----------
// "## المجال الأول — على مستوى المعارف — (8.00)"
const DOMAIN_WORDS = {
  'الأول': 1,
  'الثاني': 2,
  'الثالث': 3,
};
const domainHeadRe = /^##\s+المجال\s+(\S+)([^\n]*)$/gm;

const domains = [];
let dm;
while ((dm = domainHeadRe.exec(SRC)) !== null) {
  const word = dm[1];
  const domain = DOMAIN_WORDS[word];
  if (!domain) fail('unrecognised domain heading "' + dm[0].trim() + '".');
  const mk = dm[2].match(MARK_RE);
  domains.push({
    domain,
    declaredTotal: mk ? num(mk[1]) : null,
    start: dm.index + dm[0].length,
    headEnd: dm.index,
  });
}
if (!domains.length) fail('no "## المجال" headings found — is this a canonical file?');
domains.forEach((d, i) => {
  d.body = SRC.slice(d.start, i + 1 < domains.length ? domains[i + 1].headEnd : SRC.length);
});

// ---------- 4. Split a domain into ### blocks ----------
function blocksOf(body) {
  const out = [];
  const re = /^###\s+([^\n]+)$/gm;
  let m; const heads = [];
  while ((m = re.exec(body)) !== null) heads.push({ head: trim(m[1]), start: m.index + m[0].length, at: m.index });
  heads.forEach((h, i) => {
    out.push({ head: h.head, body: body.slice(h.start, i + 1 < heads.length ? heads[i + 1].at : body.length) });
  });
  return out;
}

// ---------- 5. Classify a block by its heading ----------
// "### 3-أ · إجابة مفتوحة · (1.00)"  |  "### مستند رقم (1)"  |  "### الوضعية"
const TYPE_WORDS = {
  'اختيار متعدد': 'mcq',
  'ربط': 'matching',
  'اشطب الدخيل': 'odd_one_out',
  'تصحيح': 'correction',
  'صح أو خطأ': 'true_false',
  'إجابة مفتوحة': 'open_reasoning',
  'استخراج': 'open_reasoning',
  'تقديم المستندين': 'components',
  'مكوّنات مطلوبة': 'components',
  'مكونات مطلوبة': 'components',
};
const DOC_RE = /^\u0645\u0633\u062A\u0646\u062F\s+\u0631\u0642\u0645\s*\((\d+)\)/;   // مستند رقم (1)
const SCENARIO_WORD = 'الوضعية';

function classify(head) {
  if (DOC_RE.test(head)) return { kind: 'document', seq: Number(head.match(DOC_RE)[1]) };
  if (head.indexOf(SCENARIO_WORD) === 0) return { kind: 'scenario' };

  const parts = head.split('·').map(trim);            // split on "·"
  if (parts.length < 3) fail('question heading is not "<رقم> · <نوع> · (علامة)": "' + head + '"');
  const idPart = parts[0];
  const typeWord = parts[1];
  const mk = parts[2].match(MARK_RE);
  if (!mk) fail('question "' + idPart + '" has no mark in its heading, or it is not in (0.00) form.');

  const t = TYPE_WORDS[typeWord];
  if (!t) fail('unknown question type "' + typeWord + '" in heading "' + head + '".');

  // "3-أ" → number 3, sub أ  |  "1" → number 1, no sub
  const im = idPart.match(new RegExp('^(\\d+)(?:\\s*[-\\u2013]\\s*(' + AR_LETTER + '))?$'));
  if (!im) fail('question id "' + idPart + '" is not a number or number-letter.');
  return { kind: 'question', number: Number(im[1]), sub: im[2] || null,
           typeWord: t, points: num(mk[1]) };
}

// ---------- 6. Field readers inside a block ----------
function sectionLines(body, label) {
  // everything after "**<label>:**" up to the next "**…:**" or blank-line boundary
  // Stop at the next field, at a horizontal rule, or at the next heading. Without the last two
  // the final key block in a domain ran on and swallowed the "---" separator, which then reached
  // the key parser as a line of dashes.
  const re = new RegExp('\\*\\*' + label + ':\\*\\*\\s*\\n?([\\s\\S]*?)'
    + '(?=\\n\\s*\\*\\*[^*]+:\\*\\*|\\n\\s*-{3,}\\s*(?:\\n|$)|\\n\\s*#{2,4}\\s|$)');
  const m = body.match(re);
  if (!m) return null;
  return m[1].split('\n')
    .filter(l => !isNote(l))
    .map(clean)
    .filter(l => !/^-{2,}$/.test(l))
    .map(l => l.replace(/^[-•]\s*/, ''))
    .filter(Boolean);
}
function inlineField(body, label) {
  const m = body.match(new RegExp('\\*\\*' + label + ':\\*\\*\\s*([^\\n]+)'));
  return m ? clean(m[1]) : null;
}
// The prompt is everything before the first "**…:**" field, minus option lists and notes.
function promptOf(body) {
  const cut = body.search(/\n\s*\*\*[^*]+:\*\*/);
  const head = (cut === -1 ? body : body.slice(0, cut));
  return head.split('\n').filter(l => !isNote(l)).map(clean).filter(Boolean).join('\n').trim();
}

const KEY_LABEL = 'المفتاح';
const REQ_LABEL = 'المطلوب';
const DISTRACT_LABEL = 'مشتتات';
const COL1_LABEL = 'العمود الأول';
const COL2_LABEL = 'العمود الثاني';

// ---------- 7. Key parsers, one per shape ----------
// Answers inside one key line are separated by ، or , or the word و, or just spaces.
const SEP = '[\u060C,\\s\u0648]+';

// "I = أ، ب (0.50)"  /  "أ→3 (0.50)"  /  "ج→2،4 (1.00)"
function parseLabelledKey(lines) {
  const byLabel = {}, points = {};
  let sawPoints = false;
  for (const raw of lines) {
    const mk = raw.match(MARK_RE);
    const body = trim(raw.replace(MARK_RE, ''));
    const m = body.match(new RegExp('^([^=\\u2192]+?)\\s*(?:=|\\u2192)\\s*(.+)$'));
    if (!m) fail('key line is not "<label> = <answers>" or "<label>→<answers>": "' + raw + '"');
    const label = trim(m[1]);
    const answers = trim(m[2]).split(new RegExp(SEP)).map(trim).filter(Boolean);
    if (!answers.length) fail('key line "' + raw + '" has no answers.');
    byLabel[label] = answers.length === 1 ? answers[0] : answers;
    if (mk) { points[label] = num(mk[1]); sawPoints = true; }
  }
  return { byLabel, points: sawPoints ? points : null };
}

// "wrong ← correct (0.50)"
function parseCorrectionKey(lines) {
  const out = {};
  lines.forEach((raw, i) => {
    const body = trim(raw.replace(MARK_RE, ''));
    const m = body.match(/^(.+?)\s*(?:←|<-)\s*(.+)$/);
    if (!m) fail('correction key line must be "<wrong> ← <correct>": "' + raw + '"');
    out[String(i + 1)] = { wrong: trim(m[1]), correct: trim(m[2]) };
  });
  return out;
}

// "صح"  /  "خطأ: <the corrected wording>"
function parseVerdictKey(lines) {
  if (lines.length !== 1) fail('a صح/خطأ key must be exactly one line.');
  const m = lines[0].match(/^(صح|خطأ)\s*(?::\s*(.+))?$/);
  if (!m) fail('صح/خطأ key must read "صح" or "خطأ: <correction>": "' + lines[0] + '"');
  return { verdict: m[1], wrong: null, correct: m[2] ? trim(m[2]) : null };
}

// "المستند رقم (1) — النوع: نص قانوني (0.25)"   (group is optional)
function parseComponentsKey(lines) {
  const groups = new Map();
  for (const raw of lines) {
    const mk = raw.match(MARK_RE);
    const body = trim(raw.replace(MARK_RE, ''));
    let group = null, rest = body;
    const gm = body.match(/^(.+?)\s+—\s+(.+)$/);       // em dash separates group from label
    if (gm) { group = trim(gm[1]); rest = trim(gm[2]); }
    const cm = rest.match(/^([^:]{1,60}):\s*(.+)$/);
    if (!cm) fail('component key line must be "<label>: <value>": "' + raw + '"');
    const k = group || '';
    if (!groups.has(k)) groups.set(k, { group: group, components: [] });
    groups.get(k).components.push({
      label: trim(cm[1]), value: trim(cm[2]), points: mk ? num(mk[1]) : null,
    });
  }
  return Array.from(groups.values());
}

// ---------- 8. Walk the file ----------
const records = [];
const seenIds = new Set();
const domainSums = [];

for (const d of domains) {
  let sum = 0;
  const blocks = blocksOf(d.body);
  if (!blocks.length) fail('domain ' + d.domain + ' has no ### blocks.');

  for (const b of blocks) {
    const c = classify(b.head);

    if (c.kind === 'document' || c.kind === 'scenario') {
      const text = b.body.split('\n').filter(l => !isNote(l)).map(clean).filter(Boolean).join('\n').trim();
      if (!text) fail('material "' + b.head + '" is empty.');
      records.push({
        recordType: 'material',
        material_id: c.kind === 'document'
          ? examId + '_d' + d.domain + '_doc' + c.seq
          : examId + '_d' + d.domain + '_scenario',
        exam_id: examId,
        domain: d.domain,
        kind: c.kind,
        seq: c.kind === 'document' ? c.seq : 1,
        text,
      });
      continue;
    }

    // ----- question -----
    // Domain 1 numbers EXERCISES; domains 2 and 3 number questions. That is the id scheme
    // already in NocoDB (civic_2019_2_d1_ex3_qxأ vs civic_2019_2_d2_q2أ) and changing it
    // would orphan every existing row rather than update it.
    const qid = d.domain === 1
      ? examId + '_d1_ex' + c.number + '_qx' + (c.sub || '')
      : examId + '_d' + d.domain + '_q' + c.number + (c.sub || '');
    if (seenIds.has(qid)) fail('duplicate question id "' + qid + '".');
    seenIds.add(qid);

    const keyLines = sectionLines(b.body, KEY_LABEL);
    if (!keyLines || !keyLines.length) fail('question "' + qid + '" has no **المفتاح:** block.');
    const reqRaw = inlineField(b.body, REQ_LABEL);
    const required = reqRaw && /^\d+$/.test(reqRaw) ? Number(reqRaw) : null;

    let type = c.typeWord, correct = null, payload = null;

    if (c.typeWord === 'matching') {
      type = 'matching';
      const { byLabel, points } = parseLabelledKey(keyLines);
      correct = { by_label: byLabel };
      if (points) correct.by_label_points = points;
      const left = sectionLines(b.body, COL1_LABEL) || [];
      const right = sectionLines(b.body, COL2_LABEL) || [];
      if (!left.length || !right.length) fail('matching "' + qid + '" is missing a column.');
      // Strip "1) " / "أ) " — Compose Reply assigns the display label from position, so leaving
      // it in the text renders "1. 1) المجلس الدستوري". Order is preserved, so the label the
      // student sees still matches the one the key uses.
      const stripLabel = t => trim(String(t)
        .replace(new RegExp('^(?:\\d{1,2}|' + AR_LETTER + ')\\s*[)\\-\\u2013.]\\s*'), ''));
      payload = { matching_left: left.map(stripLabel), matching_right: right.map(stripLabel) };
      const dis = inlineField(b.body, DISTRACT_LABEL);
      if (dis) payload.distractors = dis.split(new RegExp(SEP)).map(trim).filter(Boolean);

    } else if (c.typeWord === 'mcq' || c.typeWord === 'odd_one_out') {
      const { byLabel, points } = parseLabelledKey(keyLines);
      const multi = Object.values(byLabel).some(v => Array.isArray(v));
      type = c.typeWord === 'odd_one_out' ? 'odd_one_out' : (multi ? 'mcq_multi' : 'mcq_single');
      correct = { by_label: byLabel };
      if (points) correct.by_label_points = points;
      // Option groups for the renderer: "**المجموعة I — <title>:**" then "- أ) <option>"
      const groups = [];
      const gre = /\*\*المجموعة\s+(\S+)\s*—\s*([^*]+?):?\*\*([\s\S]*?)(?=\*\*المجموعة|\*\*[^*]+:\*\*|$)/g;
      let gm;
      while ((gm = gre.exec(b.body)) !== null) {
        groups.push({
          group_label: trim(gm[1]),
          group_title: trim(gm[2]),
          options: gm[3].split('\n').filter(l => !isNote(l)).map(clean)
            .filter(l => /^[-•]/.test(l) || new RegExp('^' + AR_LETTER + '\\s*\\)').test(l))
            .map(l => trim(l.replace(/^[-•]\s*/, '').replace(new RegExp('^' + AR_LETTER + '\\s*\\)\\s*'), '')))
            .filter(Boolean),
        });
      }
      if (groups.length) payload = { groups };

    } else if (c.typeWord === 'correction') {
      type = 'correction';
      correct = parseCorrectionKey(keyLines);

    } else if (c.typeWord === 'true_false') {
      type = 'true_false';
      correct = parseVerdictKey(keyLines);

    } else if (c.typeWord === 'components') {
      type = 'open_reasoning';
      correct = { required_components: parseComponentsKey(keyLines) };

    } else {
      type = 'open_reasoning';
      correct = { acceptable_elements: keyLines, required_count: required || keyLines.length };
      if (required && required > keyLines.length) {
        fail('question "' + qid + '" asks for ' + required + ' but its key lists only '
          + keyLines.length + '.');
      }
    }

    sum += c.points;
    records.push({
      recordType: 'question',
      question_id: qid,
      exam_id: examId,
      year,
      domain: d.domain,
      type,
      points_max: c.points,
      prompt_text: promptOf(b.body),
      payload,
      // A canonical file has nothing for a human to review. What remains is a GRADING gap:
      // nothing can score a multi-answer item yet, so those rows stay out of the exam.
      needs_review: false,
      review_notes: '',
    });
    records.push({
      recordType: 'answer',
      question_id: qid,
      correct_answer: correct,
      rubric_raw: keyLines.join('\n'),
    });
  }

  domainSums.push({ domain: d.domain, sum: Math.round(sum * 100) / 100, declared: d.declaredTotal });
}

// ---------- 9. The audit that was impossible before ----------
// The old node ran Once for Each Item with one item per domain, so it could never see the
// paper as a whole. This one reads the file, so it can check both halves of the arithmetic —
// which is the only defence against a typo in a hand-written canonical file.
for (const ds of domainSums) {
  if (ds.declared != null && Math.abs(ds.sum - ds.declared) > 0.001) {
    fail('domain ' + ds.domain + ' questions sum to ' + ds.sum
      + ' but its heading declares ' + ds.declared + '.');
  }
}
const grand = Math.round(domainSums.reduce((a, x) => a + x.sum, 0) * 100) / 100;
if (fileTotal != null && Math.abs(grand - fileTotal) > 0.001) {
  fail('the paper sums to ' + grand + ' but **المجموع:** declares ' + fileTotal + '.');
}

return records.map(r => ({ json: r }));
